-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        succession_event_id,
        predecessor_gp_id,
        successor_gp_id,
        event_type,
        effective_date,
        violation_00,
        violation_01
    from {{ ref("investment__vantora_gp_succession__checked") }}
),
violations as (
    select
        'succession_event_id_not_null' as rule_name,
        succession_event_id,
        predecessor_gp_id,
        successor_gp_id,
        event_type,
        effective_date
    from quarantined
    where violation_00

    union all

    select
        'effective_date_not_null' as rule_name,
        succession_event_id,
        predecessor_gp_id,
        successor_gp_id,
        event_type,
        effective_date
    from quarantined
    where violation_01
)

select
    rule_name,
    succession_event_id,
    predecessor_gp_id,
    successor_gp_id,
    event_type,
    effective_date
from violations
